// China in Figures — a national statistics site, as one self-contained program.
//
// Entry for best-national-statistics-site-20261126-0539 (Node 22, standard
// library only). The repository holds no app/ or screenshots/ directory: this
// single file carries the whole site as text, its screenshots as base64
// JPEGs, and the kit's dossier library as gzip+base64, and writes them out
// at run time. It runs in a fresh container with no network and a read-only
// repository, twice, and both runs must write the same bytes — so nothing
// here reads the clock, the network, or anything random: every byte written
// is fixed in this file.
//
// What it writes to /output (or $MAKEFUN_OUTPUT_DIR outside the grader):
//   app/index.html, app/style.css, app/data.js, app/main.js — the site,
//     plain static files, no build step, no request to any other origin;
//   screenshots/1-overview.jpg … 4-overview-phone.jpg — real renders of the
//     site running in a headless browser, taken while building it;
//   dossier.json — written by the kit's own buildDossier, byte for byte as
//     the scorer's copy writes it, so the gate can compare the two.
//
// The site: six pages reached by links (Overview, Economy, Population,
// Prices & Living, Regions, Sources) presenting real 2024 figures from the
// National Bureau of Statistics of China — GDP of 134,908.4 billion yuan
// (+5.0%), 1,408.28 million people, consumer prices up 0.2%, and thirteen
// provinces — with hand-drawn SVG charts and working controls: a GDP unit
// switch, a population year range, a CPI display switch, a searchable and
// sortable provinces table with a region filter and a CSV download.

import { gunzipSync } from 'node:zlib';
import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

// ---------------------------------------------------------------------------
// app/index.html — masthead, section navigation, mount point, footer.
// The pages are rendered into #app by app/main.js from app/data.js.
// ---------------------------------------------------------------------------
const INDEX_HTML = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>China in Figures — National Statistics</title>
<meta name="description" content="China's key national statistics for 2024: GDP, population, prices and the provinces, with sources, charts and tables.">
<link rel="stylesheet" href="style.css">
</head>
<body>
<header class="masthead">
  <div class="wrap masthead-in">
    <div class="brand">
      <p class="brand-mark">CN</p>
      <div>
        <h1>China in Figures</h1>
        <p class="tagline">National statistics, plainly presented</p>
      </div>
    </div>
    <p class="masthead-note">All figures: National Bureau of Statistics of China, 2024</p>
  </div>
  <nav class="wrap nav" aria-label="Sections">
    <a href="#/" data-route="">Overview</a>
    <a href="#/economy" data-route="economy">Economy</a>
    <a href="#/population" data-route="population">Population</a>
    <a href="#/prices" data-route="prices">Prices &amp; Living</a>
    <a href="#/regions" data-route="regions">Regions</a>
    <a href="#/sources" data-route="sources">Sources</a>
  </nav>
</header>
<main class="wrap" id="app" aria-live="polite"></main>
<footer class="wrap footer">
  <p>China in Figures is an independent presentation of public statistics. Figures are from the National Bureau of Statistics of China (Statistical Communiqu&eacute; of 2024, published February 2025) and the China Statistical Yearbook. Money is in current prices unless noted; growth is year on year.</p>
  <p class="footer-small">Runs entirely offline: no network request, no tracking, no cookies.</p>
</footer>
<script src="data.js"></script>
<script src="main.js"></script>
</body>
</html>
`;

// ---------------------------------------------------------------------------
// app/style.css — the whole look: paper background, ink-navy masthead,
// a restrained red accent, serif display type, cards, tables, charts.
// One breakpoint: desktop grid, then a single column on a phone.
// ---------------------------------------------------------------------------
const STYLE_CSS = `/* China in Figures — style.css. System fonts only; nothing is fetched. */
:root {
  --paper: #f7f3ea; --card: #fffdf7; --ink: #1b2733; --muted: #5b6771;
  --navy: #16283a; --red: #b3271e; --teal: #1f6f6b; --gold: #c9a227;
  --line: #e3ddd2; --soft: #eef1f3;
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--paper); color: var(--ink);
  font-family: Georgia, "Times New Roman", serif; font-size: 17px; line-height: 1.55; }
.wrap { max-width: 1020px; margin: 0 auto; padding: 0 20px; }
.masthead { background: var(--navy); color: #f4efe4; }
.masthead-in { display: flex; justify-content: space-between; align-items: center;
  gap: 16px; padding-top: 22px; padding-bottom: 8px; flex-wrap: wrap; }
.brand { display: flex; gap: 14px; align-items: center; }
.brand-mark { width: 52px; height: 52px; margin: 0; border: 2px solid var(--gold);
  border-radius: 50%; display: flex; align-items: center; justify-content: center;
  font-weight: bold; font-size: 20px; color: var(--gold); }
.brand h1 { margin: 0; font-size: 30px; line-height: 1.1; letter-spacing: .2px; }
.tagline { margin: 2px 0 0; color: #c8d2dc; font-style: italic; font-size: 15px; }
.masthead-note { margin: 0; color: #c8d2dc; font-size: 14px; max-width: 300px; text-align: right; }
.nav { display: flex; gap: 4px; flex-wrap: wrap; padding-bottom: 12px; }
.nav a { color: #dbe4ec; text-decoration: none; padding: 7px 12px; border-radius: 6px;
  font-family: -apple-system, "Segoe UI", Roboto, sans-serif; font-size: 15px; }
.nav a:hover { background: #22394f; color: #fff; }
.nav a[aria-current="page"] { background: var(--red); color: #fff; }
main { padding-top: 26px; padding-bottom: 10px; }
.page-kicker { margin: 0; color: var(--red); text-transform: uppercase;
  letter-spacing: 1.5px; font-size: 13px; font-weight: bold;
  font-family: -apple-system, "Segoe UI", Roboto, sans-serif; }
.page-title { margin: 4px 0 6px; font-size: 32px; line-height: 1.15; }
.lede { margin: 0 0 20px; color: var(--muted); max-width: 720px; }
.kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin: 0 0 22px; }
.kpi { background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 14px 16px; }
.kpi b { display: block; font-size: 26px; line-height: 1.15; }
.kpi span { color: var(--muted); font-size: 14px; }
.kpi em { display: block; font-style: normal; color: var(--teal); font-size: 14px; margin-top: 2px; }
.cards { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 22px; }
.card { background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 18px 20px; }
.card.wide { grid-column: 1 / -1; }
.card h3 { margin: 0 0 4px; font-size: 20px; }
.card p { margin: 0 0 10px; color: var(--muted); font-size: 15px; }
.chart { width: 100%; height: auto; display: block; }
.source-line { color: var(--muted); font-size: 14px; border-top: 1px solid var(--line);
  padding-top: 12px; margin: 6px 0 0; }
.controls { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin-bottom: 12px; }
.controls-label { font-family: -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 14px; font-weight: bold; }
.seg { display: inline-flex; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }
.seg button { border: 0; background: var(--card); padding: 7px 13px; cursor: pointer;
  font-family: -apple-system, "Segoe UI", Roboto, sans-serif; font-size: 14px; color: var(--ink); }
.seg button[aria-pressed="true"] { background: var(--navy); color: #fff; }
table.data { width: 100%; border-collapse: collapse; font-size: 15px; }
table.data th, table.data td { text-align: right; padding: 8px 10px; border-bottom: 1px solid var(--line); }
table.data th:first-child, table.data td:first-child { text-align: left; }
table.data th { font-family: -apple-system, "Segoe UI", Roboto, sans-serif; font-size: 13px;
  text-transform: uppercase; letter-spacing: .4px; color: var(--muted); }
table.data button.sort { all: unset; cursor: pointer; font: inherit; color: inherit; }
table.data button.sort:hover { color: var(--red); }
.toolbar { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 12px; align-items: center; }
.toolbar input, .toolbar select { padding: 8px 10px; border: 1px solid var(--line);
  border-radius: 7px; font-size: 15px; background: #fff; color: var(--ink); }
.btn { border: 0; border-radius: 7px; background: var(--red); color: #fff; padding: 9px 15px;
  cursor: pointer; font-size: 15px; font-family: -apple-system, "Segoe UI", Roboto, sans-serif; }
.btn:hover { background: #93211a; }
.fact-list { margin: 0; padding-left: 20px; }
.fact-list li { margin-bottom: 8px; }
.footer { color: var(--muted); font-size: 14px; border-top: 1px solid var(--line);
  padding-top: 16px; padding-bottom: 28px; }
.footer-small { font-size: 13px; }
@media (max-width: 720px) {
  body { font-size: 16px; }
  .brand h1 { font-size: 24px; }
  .masthead-note { display: none; }
  .kpis { grid-template-columns: 1fr 1fr; }
  .cards { grid-template-columns: 1fr; }
  .page-title { font-size: 26px; }
  .nav a { padding: 6px 9px; font-size: 14px; }
  table.data { font-size: 14px; }
}
`;

