// ---------------------------------------------------------------------------
// app/main.js — router, SVG charts, and every control. Classic scripts only,
// no modules, no network, no libraries: the whole site is these two files.
// ---------------------------------------------------------------------------
const MAIN_JS = `/* China in Figures — main.js. Renders the six pages from DATA, draws the
   charts as inline SVG, and wires every control. No network, no libraries. */
(function () {
  var app = document.getElementById("app");
  var navLinks = Array.prototype.slice.call(document.querySelectorAll(".nav a"));
  var state = { gdpUnit: "trillion", popRange: "10", cpiMode: "year", sortKey: "gdp", sortDir: -1, q: "", region: "All" };

  function esc(s) {
    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  }
  function num(n, d) { return Number(n).toLocaleString("en-US", { minimumFractionDigits: d, maximumFractionDigits: d }); }
  function head(kicker, title, lede) {
    return '<p class="page-kicker">' + esc(kicker) + '</p><h2 class="page-title">' + esc(title) + '</h2><p class="lede">' + esc(lede) + '</p>';
  }
  function sourceLine() {
    return '<p class="source-line">Source: ' + esc(DATA.meta.sourceShort) + '. Figures are in current prices unless noted; growth is year on year.</p>';
  }
  function segControl(label, name, options, current) {
    var out = '<div class="controls"><span class="controls-label">' + esc(label) + '</span><span class="seg" role="group" aria-label="' + esc(label) + '">';
    options.forEach(function (o) {
      out += '<button type="button" data-ctl="' + name + '" data-val="' + o.v + '" aria-pressed="' + (o.v === current ? "true" : "false") + '">' + esc(o.t) + '</button>';
    });
    return out + '</span></div>';
  }
  function bindSeg(name, fn) {
    var btns = app.querySelectorAll('[data-ctl="' + name + '"]');
    btns.forEach(function (b) {
      b.addEventListener("click", function () { fn(b.getAttribute("data-val")); render(); });
    });
  }

  /* ---- SVG charts, drawn from the data ---- */
  function barChart(items, opts) {
    var w = 760, h = 260, padL = 8, padR = 8, padT = 30, padB = 28;
    var max = Math.max.apply(null, items.map(function (d) { return d.value; }));
    var plotW = w - padL - padR, plotH = h - padT - padB;
    var bw = plotW / items.length, out = "";
    out += '<svg class="chart" viewBox="0 0 ' + w + ' ' + h + '" role="img" aria-label="Bar chart">';
    items.forEach(function (d, i) {
      var bh = plotH * d.value / max, x = padL + i * bw, y = padT + (plotH - bh);
      out += '<rect x="' + (x + 6).toFixed(1) + '" y="' + y.toFixed(1) + '" width="' + (bw - 12).toFixed(1) + '" height="' + bh.toFixed(1) + '" fill="' + (opts.color || "#16283a") + '" rx="2"/>';
      out += '<text x="' + (x + bw / 2).toFixed(1) + '" y="' + (padT - 8) + '" font-size="12" fill="#1b2733" text-anchor="middle">' + esc(d.note || num(d.value, 0)) + '</text>';
      out += '<text x="' + (x + bw / 2).toFixed(1) + '" y="' + (h - 8) + '" font-size="12" fill="#5b6771" text-anchor="middle">' + esc(d.label) + '</text>';
    });
    return out + '</svg>';
  }
  function lineChart(items, opts) {
    var w = 760, h = 260, padL = 46, padR = 16, padT = 24, padB = 30;
    var vals = items.map(function (d) { return d.value; });
    var min = Math.min.apply(null, vals), max = Math.max.apply(null, vals);
    if (max === min) { max = min + 1; }
    var plotW = w - padL - padR, plotH = h - padT - padB, pts = "";
    items.forEach(function (d, i) {
      var x = padL + plotW * i / (items.length - 1), y = padT + plotH * (1 - (d.value - min) / (max - min));
      pts += (i ? " L " : "M ") + x.toFixed(1) + " " + y.toFixed(1);
    });
    var out = '<svg class="chart" viewBox="0 0 ' + w + ' ' + h + '" role="img" aria-label="Line chart">';
    out += '<line x1="' + padL + '" y1="' + (h - padB) + '" x2="' + (w - padR) + '" y2="' + (h - padB) + '" stroke="#e3ddd2"/>';
    out += '<path d="' + pts + '" fill="none" stroke="' + (opts.color || "#b3271e") + '" stroke-width="3" stroke-linejoin="round"/>';
    items.forEach(function (d, i) {
      var x = padL + plotW * i / (items.length - 1), y = padT + plotH * (1 - (d.value - min) / (max - min));
      out += '<circle cx="' + x.toFixed(1) + '" cy="' + y.toFixed(1) + '" r="4" fill="' + (opts.color || "#b3271e") + '"/>';
      out += '<text x="' + x.toFixed(1) + '" y="' + (y - 10).toFixed(1) + '" font-size="12" fill="#1b2733" text-anchor="middle">' + esc(d.note || num(d.value, 1)) + '</text>';
      out += '<text x="' + x.toFixed(1) + '" y="' + (h - 8) + '" font-size="12" fill="#5b6771" text-anchor="middle">' + esc(d.label) + '</text>';
    });
    return out + '</svg>';
  }
  function hbars(items, opts) {
    var labelW = 110, rowH = 30, w = 760, h = rowH * items.length + 8;
    var max = Math.max.apply(null, items.map(function (d) { return d.value; }));
    var out = '<svg class="chart" viewBox="0 0 ' + w + ' ' + h + '" role="img" aria-label="Horizontal bar chart">';
    items.forEach(function (d, i) {
      var y = i * rowH, bw = (w - labelW - 90) * d.value / max;
      out += '<text x="' + (labelW - 8) + '" y="' + (y + 19) + '" font-size="13" fill="#1b2733" text-anchor="end">' + esc(d.label) + '</text>';
      out += '<rect x="' + labelW + '" y="' + (y + 6) + '" width="' + bw.toFixed(1) + '" height="18" fill="' + (opts.color || "#1f6f6b") + '" rx="2"/>';
      out += '<text x="' + (labelW + bw + 8).toFixed(1) + '" y="' + (y + 19) + '" font-size="13" fill="#1b2733">' + esc(d.note || num(d.value, 1)) + '</text>';
    });
    return out + '</svg>';
  }
  function donut(sectors) {
    var r = 66, C = 2 * Math.PI * r, off = 0, parts = "";
    sectors.forEach(function (s) {
      var len = C * s.share / 100;
      parts += '<circle cx="90" cy="90" r="' + r + '" fill="none" stroke="' + s.color + '" stroke-width="30" stroke-dasharray="' + len.toFixed(1) + ' ' + (C - len).toFixed(1) + '" stroke-dashoffset="' + (-off).toFixed(1) + '"/>';
      off += len;
    });
    var big = sectors[0];
    sectors.forEach(function (s) { if (s.share > big.share) { big = s; } });
    return '<svg class="chart" viewBox="0 0 180 180" style="max-width:220px;margin:0 auto" role="img" aria-label="Shares of GDP by industry">'
      + parts
      + '<text x="90" y="84" font-size="15" font-weight="bold" fill="#1b2733" text-anchor="middle">' + esc(big.short || big.label) + '</text>'
      + '<text x="90" y="104" font-size="15" fill="#5b6771" text-anchor="middle">' + big.share + '%</text></svg>';
  }

  /* ---- pages ---- */
  function kpi(value, label, note) {
    return '<div class="kpi"><b>' + value + '</b><span>' + esc(label) + '</span><em>' + esc(note) + '</em></div>';
  }
  function renderOverview() {
    var g = DATA.gdp[DATA.gdp.length - 1], p = DATA.population[DATA.population.length - 1];
    var h = head("Overview", "China in 2024, at a glance",
      "The headline numbers for the year: the size of the economy, how many people live here, what prices did, and how the country earns its living.");
    h += '<div class="kpis">'
      + kpi("\\u00a5" + num(g.value / 1000, 2) + " trillion", "Gross domestic product, 2024", "+" + DATA.gdpGrowth.toFixed(1) + "% on 2023")
      + kpi(num(p.value, 2) + "m", "Population, year-end 2024", "Down 1.39m on 2023")
      + kpi("+" + DATA.cpi[DATA.cpi.length - 1].value.toFixed(1) + "%", "Consumer prices (CPI), 2024", "Food prices fell 0.6%")
      + kpi("\\u00a5" + num(DATA.income.disposable, 0), "Disposable income per person", "Urban \\u00a554,188 · rural \\u00a523,119")
      + '</div>';
    h += '<div class="cards"><div class="card"><h3>GDP, 2015–2024</h3><p>Billion yuan, current prices.</p>'
      + barChart(DATA.gdp.map(function (d) { return { label: String(d.year), value: d.value, note: num(d.value, 0) }; }), {}) + '</div>'
      + '<div class="card"><h3>Three industries</h3><p>Share of GDP, 2024. Services now earn well over half of all output.</p>'
      + donut(DATA.structure.map(function (s) { return { label: s.label, share: s.share, color: s.color, short: s.label.split(" ")[0] }; }))
      + '<p>' + DATA.structure.map(function (s) { return esc(s.label) + " " + s.share + "%"; }).join(" · ") + '</p></div></div>';
    h += '<div class="cards"><div class="card wide"><h3>Population, 2015–2024</h3><p>Year-end resident population, millions. The population peaked in 2021 and has eased since.</p>'
      + lineChart(DATA.population.map(function (d) { return { label: String(d.year), value: d.value, note: num(d.value, 2) }; }), { color: "#1f6f6b" }) + '</div></div>';
    return h + sourceLine();
  }
  function renderEconomy() {
    var g = DATA.gdp[DATA.gdp.length - 1];
    var unit = state.gdpUnit;
    var fmt = function (v) {
      if (unit === "trillion") { return "\\u00a5" + num(v / 1000, 2) + " trillion"; }
      if (unit === "billion") { return "\\u00a5" + num(v, 1) + " billion"; }
      return "US$" + num(v / 7.19 / 1000, 2) + " trillion";
    };
    var h = head("Economy", "The economy in 2024",
      "GDP reached " + fmt(g.value) + " in 2024, up 5.0% on 2023. Growth came mostly from services and high-tech manufacturing; per-capita GDP was \\u00a595,749.");
    h += segControl("Show GDP in", "gdpUnit",
      [{ v: "trillion", t: "\\u00a5 trillion" }, { v: "billion", t: "\\u00a5 billion" }, { v: "usd", t: "US$ trillion" }], unit);
    h += '<div class="kpis">'
      + kpi(fmt(g.value), "GDP, 2024", "+5.0% year on year")
      + kpi("\\u00a595,749", "GDP per person, 2024", "About US$13,300")
      + kpi("56.7%", "Services share of GDP", "Primary 7.3% · secondary 36.0%")
      + kpi("+5.8%", "Industrial output growth", "High-tech manufacturing +8.9%")
      + '</div>';
    h += '<div class="cards"><div class="card wide"><h3>GDP by year</h3><p>Billion yuan, current prices, 2015–2024.</p>'
      + barChart(DATA.gdp.map(function (d) { return { label: String(d.year), value: d.value, note: num(d.value, 0) }; }), { color: "#b3271e" }) + '</div></div>';
    h += '<div class="cards"><div class="card"><h3>What drove growth</h3><ul class="fact-list">'
      + '<li>Services grew 5.3%; information and software services grew 10.9%.</li>'
      + '<li>Manufacturing value added rose 6.1%; new-energy vehicles output rose 38.7%.</li>'
      + '<li>Fixed-asset investment rose 3.2%; high-tech industries investment rose 8.0%.</li>'
      + '<li>Exports of goods rose 7.1% to \\u00a525.45 trillion; the trade surplus widened.</li></ul></div>'
      + '<div class="card"><h3>How to read these figures</h3><p>GDP is in current prices: the 5.0% growth rate is in real terms, after removing price changes. The US$ figure uses the year-average rate of about \\u00a57.19 per dollar and is an approximation, not an official conversion.</p></div></div>';
    return h + sourceLine();
  }
  function renderPopulation() {
    var p = DATA.population[DATA.population.length - 1];
    var n = state.popRange === "10" ? 10 : 5;
    var series = DATA.population.slice(-n);
    var h = head("Population", "1,408.28 million people",
      "China's population fell for a third straight year in 2024: 9.54 million births against 10.93 million deaths. Two in three residents now live in towns and cities.");
    h += segControl("Show years", "popRange",
      [{ v: "10", t: "2015–2024" }, { v: "5", t: "2020–2024" }], state.popRange);
    h += '<div class="kpis">'
      + kpi(num(p.value, 2) + "m", "Population, year-end 2024", "−1.39m on 2023")
      + kpi("9.54m", "Births in 2024", "Birth rate 6.77 per 1,000")
      + kpi("10.93m", "Deaths in 2024", "Death rate 7.76 per 1,000")
      + kpi(DATA.urbanShare.toFixed(1) + "%", "Urban share of population", "Up 0.84 points on 2023")
      + '</div>';
    h += '<div class="cards"><div class="card wide"><h3>Population by year</h3><p>Year-end resident population, millions.</p>'
      + lineChart(series.map(function (d) { return { label: String(d.year), value: d.value, note: num(d.value, 2) }; }), { color: "#1f6f6b" }) + '</div></div>';
    h += '<div class="cards"><div class="card"><h3>An ageing country</h3><ul class="fact-list">'
      + '<li>People aged 60 and over: 310.31 million, 22.0% of the population.</li>'
      + '<li>People aged 65 and over: 220.23 million, 15.6% of the population.</li>'
      + '<li>Working-age people (16–59): 857.98 million, 60.9% of the population.</li></ul></div>'
      + '<div class="card"><h3>Cities keep growing</h3><p>The urban population reached 943.50 million in 2024, up 10.83 million on the year, while the rural population fell to 464.78 million. Urbanisation has risen every year for four decades.</p></div></div>';
    return h + sourceLine();
  }
  function renderPrices() {
    var last = DATA.cpi[DATA.cpi.length - 1];
    var h = head("Prices & Living", "Prices barely moved in 2024",
      "Consumer prices rose just 0.2% in 2024 — the second flat year in a row. Food got cheaper while services got dearer, and incomes rose faster than prices.");
    h += segControl("Show CPI as", "cpiMode",
      [{ v: "year", t: "Yearly change" }, { v: "level", t: "Index (2020 = 100)" }], state.cpiMode);
    var idx = 100;
    var items = DATA.cpi.map(function (d, i) {
      if (i > 0) { idx = idx * (1 + d.value / 100); }
      var v = state.cpiMode === "year" ? d.value : idx;
      return { label: String(d.year), value: v, note: (state.cpiMode === "year" ? "+" : "") + v.toFixed(1) + (state.cpiMode === "year" ? "%" : "") };
    });
    h += '<div class="kpis">'
      + kpi("+" + last.value.toFixed(1) + "%", "CPI, 2024", "Same as 2023")
      + kpi("−0.6%", "Food prices, 2024", "Pork prices fell 9.6%")
      + kpi("+0.5%", "Services prices, 2024", "Education and travel dearer")
      + kpi("+5.3%", "Real income growth", "Disposable income, price-adjusted")
      + '</div>';
    h += '<div class="cards"><div class="card"><h3>Consumer prices by year</h3><p>' + (state.cpiMode === "year" ? "Annual change in the consumer price index, %." : "Price index, 2020 = 100, compounded from the yearly changes.") + '</p>'
      + barChart(items, { color: "#1f6f6b" }) + '</div>'
      + '<div class="card"><h3>Living standards</h3><ul class="fact-list">'      + '<li>Disposable income per person: \\u00a541,314 (+5.3% in real terms).</li>'
      + '<li>Urban residents: \\u00a554,188; rural residents: \\u00a523,119 — a ratio of 2.34 to 1.</li>'
      + '<li>Per-capita consumption spending: \\u00a528,227, up 5.3% in real terms.</li>'
      + '<li>Engel coefficient (food share of spending): 29.8%.</li></ul></div></div>';
    h += '<div class="cards"><div class="card wide"><h3>What cost more — and less</h3><p>Fresh vegetables rose 2.8% and fruit 3.1%, while pork, the single biggest food item, fell sharply after supply recovered. Housing rents were flat; transport and communication prices fell 1.4% as fuel got cheaper. The overall picture is a low-inflation year: demand was soft, and supply of most goods was ample.</p></div></div>';
    return h + sourceLine();
  }
  function filteredProvinces() {
    var q = state.q.toLowerCase();
    return DATA.provinces.filter(function (p) {
      var okRegion = state.region === "All" || p.region === state.region;
      var okQ = !q || p.name.toLowerCase().indexOf(q) !== -1;
      return okRegion && okQ;
    }).sort(function (a, b) {
      var k = state.sortKey, d = state.sortDir;
      var av = k === "name" ? a.name : (k === "gdp" ? a.gdp : (k === "pop" ? a.pop : a.gdp / a.pop * 1000));
      var bv = k === "name" ? b.name : (k === "gdp" ? b.gdp : (k === "pop" ? b.pop : b.gdp / b.pop * 1000));
      if (av < bv) { return -d; }
      if (av > bv) { return d; }
      return 0;
    });
  }
  function renderRegions() {
    var rows = filteredProvinces();
    var h = head("Regions", "The provinces, ranked",
      "Thirteen provinces and municipalities, by GDP in 2024. Search by name, filter by region, sort any column, or download the table as a CSV file.");
    h += '<div class="toolbar"><input id="q" type="search" placeholder="Search a province…" value="' + esc(state.q) + '" aria-label="Search provinces">'
      + '<select id="region" aria-label="Filter by region">'
      + ["All", "East", "Central", "West"].map(function (r) { return '<option' + (state.region === r ? ' selected' : '') + '>' + r + '</option>'; }).join("")
      + '</select><button class="btn" id="csv" type="button">Download CSV</button></div>';
    h += '<div class="card wide"><table class="data"><thead><tr>'
      + '<th><button class="sort" type="button" data-sort="name">Province</button></th>'
      + '<th>Region</th>'
      + '<th><button class="sort" type="button" data-sort="gdp">GDP, \\u00a5bn</button></th>'
      + '<th><button class="sort" type="button" data-sort="pop">Population, m</button></th>'
      + '<th><button class="sort" type="button" data-sort="pc">GDP per person, \\u00a5</button></th>'
      + '</tr></thead><tbody>';
    rows.forEach(function (p) {
      h += '<tr><td>' + esc(p.name) + '</td><td>' + esc(p.region) + '</td><td>' + num(p.gdp, 1) + '</td><td>' + num(p.pop, 2) + '</td><td>' + num(p.gdp / p.pop * 1000, 0) + '</td></tr>';
    });
    h += '</tbody></table><p class="source-line">' + rows.length + ' of 13 provinces shown. GDP per person is computed from the two columns. Source: ' + esc(DATA.meta.sourceShort) + '.</p></div>';
    h += '<div class="cards"><div class="card wide"><h3>Biggest provincial economies</h3><p>GDP, billion yuan, 2024.</p>'
      + hbars(DATA.provinces.slice(0, 8).map(function (p) { return { label: p.name, value: p.gdp, note: num(p.gdp, 1) }; }), {}) + '</div></div>';
    return h;
  }
  function bindRegions() {
    var q = document.getElementById("q"), region = document.getElementById("region"), csv = document.getElementById("csv");
    if (q) { q.addEventListener("input", function () { state.q = q.value; renderRegionsOnly(); }); }
    if (region) { region.addEventListener("change", function () { state.region = region.value; render(); }); }
    if (csv) {
      csv.addEventListener("click", function () {
        var lines = ["Province,Region,GDP (billion yuan),Population (million),GDP per person (yuan)"];
        filteredProvinces().forEach(function (p) {
          lines.push([p.name, p.region, p.gdp, p.pop, Math.round(p.gdp / p.pop * 1000)].join(","));
        });
        var blob = new Blob([lines.join("\\n")], { type: "text/csv" });
        var a = document.createElement("a");
        a.href = URL.createObjectURL(blob);
        a.download = "china-provinces-2024.csv";
        a.click();
        URL.revokeObjectURL(a.href);
      });
    }
    app.querySelectorAll("[data-sort]").forEach(function (b) {
      b.addEventListener("click", function () {
        var k = b.getAttribute("data-sort");
        if (state.sortKey === k) { state.sortDir = -state.sortDir; } else { state.sortKey = k; state.sortDir = k === "name" ? 1 : -1; }
        render();
      });
    });
  }
  function renderRegionsOnly() {
    render();
    var q = document.getElementById("q");
    if (q) { q.focus(); q.setSelectionRange(q.value.length, q.value.length); }
  }
  function renderSources() {
    var h = head("Sources & methods", "Where every figure comes from",
      "Every number on this site is published by the National Bureau of Statistics of China or a provincial statistics bureau. No figure is estimated by this site except where it says so.");
    h += '<div class="cards"><div class="card wide"><h3>Sources</h3><ul class="fact-list">';
    DATA.sources.forEach(function (s) {
      h += '<li><b>' + esc(s.name) + '</b> (' + esc(s.date) + ') — ' + esc(s.what) + '</li>';
    });
    h += '</ul></div></div>';
    h += '<div class="cards"><div class="card"><h3>Methods</h3><ul class="fact-list">'
      + '<li>GDP is in current prices; growth rates are in real terms.</li>'
      + '<li>Population is year-end resident population, including migrants.</li>'
      + '<li>Provincial GDP per person is computed here from provincial GDP and population.</li>'
      + '<li>The US$ conversion uses the 2024 average rate of about \\u00a57.19 per dollar.</li></ul></div>'
      + '<div class="card"><h3>What is not here</h3><p>This site covers the national headline figures only. It does not republish the full Yearbook tables, county data, or monthly series — those live with the National Bureau of Statistics, and the communiqu&eacute; is the place to start.</p></div></div>';
    return h + '<p class="source-line">' + esc(DATA.meta.sourceLong) + '</p>';
  }

  /* ---- router ---- */
  var routes = {
    "": { title: "Overview", fn: renderOverview },
    "economy": { title: "Economy", fn: renderEconomy },
    "population": { title: "Population", fn: renderPopulation },
    "prices": { title: "Prices & Living", fn: renderPrices },
    "regions": { title: "Regions", fn: renderRegions },
    "sources": { title: "Sources & methods", fn: renderSources }
  };
  function render() {
    var h = window.location.hash, r = "";
    if (h.indexOf("#/") === 0) { r = h.slice(2).split("/")[0]; }
    if (!routes[r]) { r = ""; }
    app.innerHTML = routes[r].fn();
    document.title = routes[r].title + " — China in Figures";
    navLinks.forEach(function (a) {
      if (a.getAttribute("data-route") === r) { a.setAttribute("aria-current", "page"); } else { a.removeAttribute("aria-current"); }
    });
    bindSeg("gdpUnit", function (v) { state.gdpUnit = v; });
    bindSeg("popRange", function (v) { state.popRange = v; });
    bindSeg("cpiMode", function (v) { state.cpiMode = v; });
    if (r === "regions") { bindRegions(); }
  }
  window.addEventListener("hashchange", function () { render(); window.scrollTo(0, 0); });
  render();
})();
`;

// ---------------------------------------------------------------------------
// Screenshots and the dossier library, as data. The screenshots are real
// renders of this site, taken with a headless browser while building it;
// each value is one base64 JPEG on one line. The library is the kit's
// vendor/makefun-frontend.ts, gzipped and base64, on one line. Both are
// filled in after the site is built and shot; until then the runner below
// still writes app/ so the site can be served and screenshotted.
// ---------------------------------------------------------------------------
const SHOTS_B64: Record<string, string> = {
  '1-overview.jpg': '',
  '2-economy.jpg': '',
  '3-regions.jpg': '',
  '4-overview-phone.jpg': '',
};
const LIB_GZ_B64 = "";

// ---------------------------------------------------------------------------
// The hand-in: write app/ and screenshots/ to /output, then dossier.json
// with the kit's own buildDossier. Deterministic: no clock, no network,
// no randomness — two runs write the same bytes.
// ---------------------------------------------------------------------------
const here = fileURLToPath(new URL('.', import.meta.url));
const out = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';

const APP: Record<string, string> = {
  'index.html': INDEX_HTML,
  'style.css': STYLE_CSS,
  'data.js': DATA_JS,
  'main.js': MAIN_JS,
};

rmSync(join(out, 'app'), { recursive: true, force: true });
rmSync(join(out, 'screenshots'), { recursive: true, force: true });
mkdirSync(join(out, 'app'), { recursive: true });
for (const [name, text] of Object.entries(APP)) writeFileSync(join(out, 'app', name), text);

const shotNames = Object.keys(SHOTS_B64).sort();
if (shotNames.length > 0) {
  mkdirSync(join(out, 'screenshots'), { recursive: true });
  for (const name of shotNames) writeFileSync(join(out, 'screenshots', name), Buffer.from(SHOTS_B64[name], 'base64'));
}

if (LIB_GZ_B64) {
  const libPath = join(tmpdir(), 'makefun-frontend-' + process.pid + '.ts');
  writeFileSync(libPath, gunzipSync(Buffer.from(LIB_GZ_B64, 'base64')));
  const { buildDossier } = await import(pathToFileURL(libPath).href);
  writeFileSync(
    join(out, 'dossier.json'),
    buildDossier(out, {
      text_max_bytes: 163840,
      screenshots: { max: 4, max_bytes: 262144 },
      app_max_files: 993,
      app_max_bytes: 16777216,
    }),
  );
  rmSync(libPath, { force: true });
  console.log('wrote ' + out + ' (app, ' + shotNames.length + ' screenshots, dossier.json)');
} else {
  console.log('wrote ' + out + '/app (' + shotNames.length + ' screenshots embedded); dossier skipped: library not embedded yet');
}
void here;
